// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"REST",0,1],[48,"A",0,1],[64,"A",0,1],[80,"A",0,1],[96,"A",0,1],[112,"A",0,1],[128,"A",0,1],[144,"REST",0,1],[176,"REST",0,1],[208,"REST",0,1],[224,"A",0,1],[240,"A",0,1],[256,"A",0,1],[272,"A",0,1],[288,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"B",0,1],[48,"REST",0,1],[144,"BRIDGE",0,1],[160,"BRIDGE",0,1],[176,"SOLO",0,1],[208,"RUN",0,1],[224,"REST",0,1],[288,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[48,"REST",0,1],[144,"REST",0,1],[176,"REST",0,1],[208,"REST",0,1],[224,"HARMONY",0,1],[288,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- glass -------------------------------------------------------------------------------------
const track0 = {
  color: '#9fe8ff',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["G = \\Rev\\,\\Dly\\Big[v\\big(0.6e^{-2.2t}\\sin(2\\pi ft + 1.3e^{-7t}\\sin 2\\pi\\,2.005ft) + 0.3e^{-4t}\\sin(4\\pi ft + 0.7e^{-10t}\\sin 2\\pi\\,6.02ft)\\big)\\Big]\\ \\text{— стеклянный отзвук мотива}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly((f, t, v) => v * (0.6 * fm(f, t, { ratio: 2.005, index: 1.3, decay: 2.2, idecay: 7 }) + 0.3 * fm(2 * f, t, { ratio: 3.01, index: 0.7, decay: 4, idecay: 10 })), { release: 0.6, life: 4 }), fire = trigger(), echo = delay({ time: sec * 0.75, feedback: 0.45, wet: 0.32 }), verb = reverb({ room: 0.92, damp: 0.3, wet: 0.42 })
    return x => {
      const m = leadAt(x)
      if (fire(m ? m.at : null)) p.hit(hz(m.n, C4), 0.7 + 0.2 * hash(floor(4 * x), 3), m.d * sec + 0.6)
      const y = 0.4 * p() * pumpAt(x)
      return verb(...echo(...pan(y, 0.12)))
    }
  },
}

